llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Hydrocortisone, a rigid polycyclic corticosteroid with multiple hydroxyl and carbonyl groups, has an absolute oral bioavailability of 0.95 in healthy adults, showing that a polar, rigid fused-ring molecule can be essentially completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Methylprednisolone, a close corticosteroid analogue, has an absolute oral bioavailability of about 82%, supporting high F for oxygenated polycyclic steroids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Amoxicillin, a very polar small molecule with many H-bond donors and acceptors, has a mean absolute oral bioavailability of 77.4% in humans, demonstrating that high polarity does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "9-Aminocamptothecin, a rigid lactone-containing molecule, has approximately 50% oral bioavailability in humans, directly supporting that lactone rings are compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "Finasteride, a steroid-like fused-ring molecule, has a systemic bioavailability of 63% (range 34–108%) after oral dosing, supporting high oral absorption for this scaffold class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Naltrexone has very poor oral bioavailability (~5–10%) due to extensive first-pass metabolism, but it contains a basic tertiary amine and phenol and has the lowest transfer score; its metabolic liability is not representative of the neutral lactone-rich query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest and most transferable experimental evidence—from corticosteroids, amoxicillin, a lactone-containing camptothecin, and finasteride—consistently shows oral bioavailability at or above 20%, often much higher. The only low-bioavailability analogue (naltrexone) is structurally dissimilar and has the lowest transfer score. The physicochemical prior is uncertain and is outweighed by this experimental pattern.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the exact query molecule.",
    "Lactone stability and esterase-mediated hydrolysis of the three lactone rings in vivo are unknown.",
    "Potential efflux transporter interactions have not been experimentally characterized.",
    "Species-specific differences in first-pass metabolism were not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

